	@Test
	void planSyntheticIdsWithOrderedIntegerBitsUseTheirRdfValuesForComparison() {
		Value leftValue = iri("z");
		Value rightValue = iri("a");
		CatalogValues values = catalogValues(leftValue, rightValue);
		SyntheticValueSource source = evaluationSource(values.catalog);
		RowState row = row(source);
		LmdbNativeKernelHooks hooks = hooks(row);
		try {
			assertThat(values.firstId).isNotEqualTo(values.secondId);
			assertThat(ValueIds.isOrderedInteger(values.firstId)).isTrue();
			assertThat(ValueIds.isOrderedInteger(values.secondId)).isTrue();
			assertThat(source.authority().kind(values.firstId)).isEqualTo(NativeIdKind.PLAN);
			assertThat(source.authority().kind(values.secondId)).isEqualTo(NativeIdKind.PLAN);

			int expected = Integer.signum(new ValueComparator().compare(leftValue, rightValue));
			assertThat(Integer.signum(hooks.compareValues(values.firstId, values.secondId)))
					.as("plan ids must not be compared as backing-store ordered-integer ids")
					.isEqualTo(expected);
		} finally {
			close(hooks, row, source);
		}
	}

